import * as React from "react"

function AnOffLineGameOfCatchingAfox({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="an-off-line-game-of-catching-afox"
      className={className}
      {...props}
    >
      <style>{".fox {\n      position: absolute;\n      font-size: 2rem;\n      cursor: pointer;\n      transition: transform 0.2s ease;\n    }\n    .fox:active {\n      transform: scale(1.2);\n    }"}</style>
      <h1 className="text-3xl font-bold mb-4 text-orange-600">🦊 Catch the Fox!</h1>
        <p className="mb-2 text-lg">Click the fox as many times as you can in <span id="time" className="font-bold">15</span> seconds!</p>
        <p className="mb-6 text-xl">Score: <span id="score" className="font-bold text-blue-600">0</span></p>

        <div id="gameArea" className="relative w-[300px] h-[300px] bg-white rounded-lg shadow-lg overflow-hidden">
          <div id="fox" className="fox">🦊</div>
        </div>

        <button className="mt-6 bg-orange-500 text-white px-4 py-2 rounded hover:bg-orange-600">
          Start Game
        </button>
    </div>
  )
}

export { AnOffLineGameOfCatchingAfox }
